<script>
(function () {
    'use strict';
    var form = document.getElementById('invoice-form');
    if (!form) return;
    var submitted = false;
    form.addEventListener('submit', function (e) {
        if (submitted) { e.preventDefault(); return; }
        submitted = true;
    });
})();
</script>
